import sys

MOD = 1000000007

def count_palindromes(N):
    if N == 1:
        return 26
    elif N == 2:
        return 52
    else:
        half = (N + 1) // 2
        result = pow(26, half, MOD)
        if N % 2 == 1:
            result = (result * 26) % MOD
        return result

def main():
    import sys
    input = sys.stdin.read().split()
    T = int(input[0])
    index = 1
    results = []
    for _ in range(T):
        N = int(input[index])
        results.append(count_palindromes(N))
        index += 1
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
